const rows = $('Traer conversaciones del dia').all().map(i => i.json);
const adSessions = new Set($input.all().map(i => i.json.session_id));

const bySession = {};
for (const r of rows) {
  if (!bySession[r.session_id]) bySession[r.session_id] = [];
  bySession[r.session_id].push({ role: r.role, content: r.content, created_at: r.created_at });
}

// Biotina Pura - precios por cantidad y costo real (costo de producto +
// envio por pedido, el envio no se multiplica por unidad)
const UNIDADES_POR_MONTO = { 35000: 1, 45000: 2, 60000: 3 };
const COSTO_PRODUCTO_UNIT = 3500;
const COSTO_ENVIO_POR_PEDIDO = 10000;
// Fallback para conversaciones viejas del Combo Biotina (precio fijo, ya
// no se vende, pero puede quedar alguna en el dia de la migracion)
const PRECIO_FALLBACK = 43000;
const COSTO_FALLBACK = 10000;

function gananciaDeVenta(monto) {
  const unidades = UNIDADES_POR_MONTO[monto];
  if (unidades) return monto - (COSTO_PRODUCTO_UNIT * unidades + COSTO_ENVIO_POR_PEDIDO);
  return monto - COSTO_FALLBACK;
}

// Numeros del dueno y del equipo (Dolores) - no son clientes reales, se
// excluyen aunque hayan entrado marcados como origen de anuncio (pruebas)
const EXCLUDED_NUMBERS = new Set(['5491140377694', '5491161558641']);

// Arranque del dia de hoy en Argentina, para saber si un comprobante
// llego HOY (aunque la conversacion haya arrancado otro dia - la mayoria
// de las ventas tardan varios dias en cerrar)
const now = new Date();
const argNow = new Date(now.toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' }));
const todayStartArg = new Date(argNow.getFullYear(), argNow.getMonth(), argNow.getDate());
const offsetMs = now.getTime() - argNow.getTime();
const todayStartUTC = new Date(todayStartArg.getTime() + offsetMs);

let totalConversaciones = 0;
let ventasCerradas = 0;
let facturacion = 0;
let ganancia = 0;

for (const [sessionId, msgs] of Object.entries(bySession)) {
  if (!adSessions.has(sessionId)) continue; // solo conversaciones que en algun momento vinieron de un anuncio
  const numberOnly = sessionId.split('@')[0];
  if (EXCLUDED_NUMBERS.has(numberOnly)) continue;

  const hasActivityToday = msgs.some(m => new Date(m.created_at) >= todayStartUTC);
  if (hasActivityToday) totalConversaciones++;

  // Venta cerrada HOY = llego un comprobante verificado como real HOY,
  // sin importar si la conversacion o el pago inicial fueron otro dia
  const receiptToday = msgs.some(m =>
    m.role === 'user' &&
    m.content.startsWith('[Comprobante de pago recibido]') &&
    new Date(m.created_at) >= todayStartUTC
  );
  if (!receiptToday) continue;

  const paymentMsg = [...msgs].reverse().find(m => m.role === 'assistant' && (m.content.includes('CBU: 3840200500000054291199') || m.content.includes('Alias: productoscapilarespg')));
  if (!paymentMsg) continue; // no deberia pasar, pero por seguridad no sumar sin monto conocido

  ventasCerradas++;
  const montoMatch = paymentMsg.content.match(/\$\s?([\d.]+)/);
  const monto = montoMatch ? parseInt(montoMatch[1].replace(/\./g, ''), 10) : PRECIO_FALLBACK;
  facturacion += monto;
  ganancia += gananciaDeVenta(monto);
}

const conversionPct = totalConversaciones > 0 ? ((ventasCerradas / totalConversaciones) * 100).toFixed(1) : '0.0';
const fmt = n => n.toLocaleString('es-AR');

const hoy = new Date().toLocaleDateString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', day: '2-digit', month: '2-digit', year: 'numeric' });

let text = `📅 Resumen del dia (${hoy})\n\n`;
text += `💬 Conversaciones desde anuncios: ${totalConversaciones}\n`;
text += `🛒 Ventas cerradas: ${ventasCerradas}\n`;
text += `📈 Conversion: ${conversionPct}%\n`;
if (ventasCerradas > 0) {
  text += `💰 Facturacion: $${fmt(facturacion)}\n`;
  text += `✅ Ganancia neta: $${fmt(ganancia)}`;
} else {
  text += `💰 Sin ventas cerradas hoy.`;
}

return [{ json: { text } }];

const rows = $('Traer conversaciones del dia').all().map(i => i.json);
const adSessions = new Set($input.all().map(i => i.json.session_id));

const EXCLUDED_NUMBERS = new Set(['5491140377694', '5491161558641']);

const bySession = {};
for (const r of rows) {
  if (!bySession[r.session_id]) bySession[r.session_id] = [];
  bySession[r.session_id].push({ role: r.role, content: r.content });
}

const conversaciones = [];
for (const [sessionId, msgs] of Object.entries(bySession)) {
  if (!adSessions.has(sessionId)) continue;
  const numberOnly = sessionId.split('@')[0];
  if (EXCLUDED_NUMBERS.has(numberOnly)) continue;
  const userMsgs = msgs.filter(m => m.role === 'user').map(m => m.content);
  if (userMsgs.length === 0) continue;
  conversaciones.push({ numero: numberOnly.slice(-4), mensajes: userMsgs });
}

if (conversaciones.length === 0) {
  return [{ json: { skip: true, prompt: '' } }];
}

const listado = conversaciones.map((c, i) =>
  `Conversacion ${i + 1} (termina en ...${c.numero}):\n` + c.mensajes.map(m => '- ' + m).join('\n')
).join('\n\n');

const prompt = `Sos un analista que evalua la calidad de los leads que llegan por WhatsApp desde anuncios de Meta Ads de un negocio que vende Biotina Pura (spray para caida de pelo). Te paso todas las conversaciones de HOY que empezaron desde un anuncio (solo los mensajes del cliente, no las respuestas del bot).

Clasificalas en:
- Contenido real: el cliente cuenta su problema de pelo (caida, quiebre, no crece, etc), pregunta precio, ubicacion, forma de pago, o cualquier cosa relacionada con comprar
- Solo saludo: unicamente mando el mensaje automatico de WhatsApp Ads sin agregar nada mas
- Baja calidad: parece spam, cuenta de negocio ajena, broma, o claramente no es un cliente real

Ademas marca especificamente los casos que esten MUY cerca de cerrar la venta (ya dieron todos los datos de envio, dijeron que van a transferir, o son clientes que ya compraron antes y quieren repetir).

Escribi un reporte corto en espanol rioplatense, tono directo tipo WhatsApp (como si se lo mandaras al dueno del negocio), con esta estructura aproximada (adaptala a los numeros reales, no inventes datos que no esten en las conversaciones):

Resultado: [dato de calidad general en una linea]

- X de Y (Z%) escribieron contenido real...
- N casos ya estan cerca de cerrar: [detalle breve de cada uno]
- N de Y solo mandaron el saludo...
- N caso(s) de baja calidad si los hay: [detalle breve]

En criollo: [conclusion de 1-2 lineas]

IMPORTANTE: no uses formato markdown (nada de asteriscos, numerales ni guiones bajos), es texto plano para mandar directo por WhatsApp - los guiones de lista simples estan bien. Se breve, es un reporte diario.

Conversaciones de hoy:

${listado}`;

return [{ json: { prompt, skip: false } }];

